    fun all(): List<WarmupResource> = resources.toList()
    fun forRegion(region: String) = resources.filter { it.region.equals(region, true) }
    fun pinned() = resources.filter { it.pinned }
    fun withinBudget(bytes: Int) = resources.filter { it.estimatedBytes <= bytes }
    fun totalEstimate(): Long = resources.sumOf { it.estimatedBytes.toLong() }
